use std :: hash :: { DefaultHasher , Hash , Hasher } ; use std :: path :: PathBuf ; use derive_more :: Display ; use derive_setters :: Setters ; use serde :: { Deserialize , Serialize } ; use crate :: { Effort , ModelConfig } ; use fake :: { Fake , Faker } ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " All discrete mutations that can be applied to the application configuration."] # [doc = ""] # [doc = " Instead of replacing the entire config, callers describe exactly which field"] # [doc = " they want to change. Implementations receive a list of operations, apply"] # [doc = " each in order, and persist the result atomically."] # [derive (Debug , Clone , PartialEq)] pub enum ConfigOperation { # [doc = " Set the active session provider and model atomically."] # [doc = ""] # [doc = " When the provider differs from the current session provider the entire"] # [doc = " session (provider + model) is replaced atomically. When they match only"] # [doc = " the model field is updated."] SetSessionConfig (ModelConfig) , # [doc = " Set the commit-message generation configuration."] # [doc = ""] # [doc = " `None` clears the commit configuration so the active session"] # [doc = " provider/model is used for commit message generation."] SetCommitConfig (Option < ModelConfig >) , # [doc = " Set the shell-command suggestion configuration."] SetSuggestConfig (ModelConfig) , # [doc = " Set the reasoning effort level for all agents."] SetReasoningEffort (Effort) , }